INSERT INTO notification_template (uuid, company_id, code, name, channel, subject, content_template, content_type, variables, locale, is_active, is_system) VALUES
(UUID(), NULL, 'EMPLOYEE_HIRED', 'Contratação de Funcionário', 'EMAIL', 'Bem-vindo à {{company_name}}!', '<h1>Olá {{employee_name}},</h1><p>Seja bem-vindo à <strong>{{company_name}}</strong>!</p><p>Seu número de matrícula é: <strong>{{employee_number}}</strong></p><p>Data de admissão: {{hire_date}}</p><p>Cargo: {{position_title}}</p><p>Departamento: {{department_name}}</p><p>Estamos felizes em tê-lo conosco!</p><p>Atenciosamente,<br>Equipe de RH</p>', 'HTML', '["employee_name", "company_name", "employee_number", "hire_date", "position_title", "department_name"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'EMPLOYEE_HIRED', 'Contratação de Funcionário', 'WHATSAPP', NULL, 'Olá {{employee_name}}! 🎉\n\nSeja bem-vindo à *{{company_name}}*!\n\n📋 Matrícula: {{employee_number}}\n📅 Admissão: {{hire_date}}\n💼 Cargo: {{position_title}}\n🏢 Departamento: {{department_name}}\n\nEstamos felizes em tê-lo conosco!\n\nEquipe de RH', 'TEXT', '["employee_name", "company_name", "employee_number", "hire_date", "position_title", "department_name"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'EMPLOYEE_TERMINATED', 'Desligamento de Funcionário', 'EMAIL', 'Comunicado de Desligamento - {{employee_name}}', '<h1>Comunicado de Desligamento</h1><p>Informamos o desligamento do funcionário <strong>{{employee_name}}</strong> (Matrícula: {{employee_number}}).</p><p><strong>Data de desligamento:</strong> {{termination_date}}</p><p><strong>Motivo:</strong> {{termination_reason}}</p><p><strong>Aviso prévio:</strong> {{notice_period}} dias</p><p>As verbas rescisórias serão calculadas e pagas conforme legislação vigente.</p><p>Atenciosamente,<br>Equipe de RH</p>', 'HTML', '["employee_name", "employee_number", "termination_date", "termination_reason", "notice_period"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'PAYROLL_PROCESSED', 'Folha de Pagamento Processada', 'EMAIL', 'Folha de {{reference_month}}/{{reference_year}} - Disponível', '<h1>Folha de Pagamento Processada</h1><p>A folha de pagamento referente a <strong>{{reference_month}}/{{reference_year}}</strong> foi processada com sucesso.</p><p><strong>Total de funcionários:</strong> {{total_employees}}</p><p><strong>Total bruto:</strong> {{total_gross_amount}}</p><p><strong>Total líquido:</strong> {{total_net_amount}}</p><p>Os holerites estão disponíveis no portal do colaborador.</p><p>Atenciosamente,<br>Equipe de RH</p>', 'HTML', '["reference_month", "reference_year", "total_employees", "total_gross_amount", "total_net_amount"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'PAYSLIP_AVAILABLE', 'Holerite Disponível', 'EMAIL', 'Seu holerite de {{reference_month}}/{{reference_year}} está disponível', '<h1>Holerite Disponível</h1><p>Olá <strong>{{employee_name}}</strong>,</p><p>Seu holerite referente a <strong>{{reference_month}}/{{reference_year}}</strong> está disponível para consulta.</p><p><strong>Salário bruto:</strong> {{gross_amount}}</p><p><strong>Salário líquido:</strong> {{net_amount}}</p><p><a href="{{payslip_url}}">Acessar holerite</a></p><p>Atenciosamente,<br>Equipe de RH</p>', 'HTML', '["employee_name", "reference_month", "reference_year", "gross_amount", "net_amount", "payslip_url"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'PAYSLIP_AVAILABLE', 'Holerite Disponível', 'WHATSAPP', NULL, 'Olá {{employee_name}}! 📄\n\nSeu holerite de *{{reference_month}}/{{reference_year}}* está disponível.\n\n💰 Bruto: {{gross_amount}}\n💵 Líquido: {{net_amount}}\n\n🔗 Acesse: {{payslip_url}}\n\nEquipe de RH', 'TEXT', '["employee_name", "reference_month", "reference_year", "gross_amount", "net_amount", "payslip_url"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'LEAVE_APPROVED', 'Licença Aprovada', 'EMAIL', 'Sua licença foi aprovada - {{leave_type_name}}', '<h1>Licença Aprovada ✅</h1><p>Olá <strong>{{employee_name}}</strong>,</p><p>Sua solicitação de <strong>{{leave_type_name}}</strong> foi <span style="color: green;"><strong>APROVADA</strong></span>.</p><p><strong>Período:</strong> {{start_date}} a {{end_date}}</p><p><strong>Total de dias:</strong> {{total_days}}</p>{{#if approval_notes}}<p><strong>Observações:</strong> {{approval_notes}}</p>{{/if}}<p>Atenciosamente,<br>Equipe de RH</p>', 'HTML', '["employee_name", "leave_type_name", "start_date", "end_date", "total_days", "approval_notes"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'LEAVE_REJECTED', 'Licença Rejeitada', 'EMAIL', 'Sua licença foi rejeitada - {{leave_type_name}}', '<h1>Licença Rejeitada ❌</h1><p>Olá <strong>{{employee_name}}</strong>,</p><p>Sua solicitação de <strong>{{leave_type_name}}</strong> foi <span style="color: red;"><strong>REJEITADA</strong></span>.</p><p><strong>Período solicitado:</strong> {{start_date}} a {{end_date}}</p><p><strong>Motivo:</strong> {{rejection_reason}}</p><p>Caso tenha dúvidas, entre em contato com o RH.</p><p>Atenciosamente,<br>Equipe de RH</p>', 'HTML', '["employee_name", "leave_type_name", "start_date", "end_date", "rejection_reason"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'TIME_SHEET_CLOSED', 'Fechamento de Ponto', 'EMAIL', 'Fechamento de ponto - {{reference_month}}/{{reference_year}}', '<h1>Fechamento de Ponto</h1><p>Olá <strong>{{employee_name}}</strong>,</p><p>O fechamento de ponto referente a <strong>{{reference_month}}/{{reference_year}}</strong> foi realizado.</p><p><strong>Horas trabalhadas:</strong> {{total_worked_hours}}</p><p><strong>Horas extras:</strong> {{total_overtime_hours}}</p><p><strong>Horas noturnas:</strong> {{total_night_hours}}</p><p><strong>Faltas:</strong> {{total_absence_hours}} horas</p><p><strong>Atrasos:</strong> {{total_late_minutes}} minutos</p><p>Caso identifique alguma divergência, entre em contato com o RH em até 48h.</p><p>Atenciosamente,<br>Equipe de RH</p>', 'HTML', '["employee_name", "reference_month", "reference_year", "total_worked_hours", "total_overtime_hours", "total_night_hours", "total_absence_hours", "total_late_minutes"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'BIRTHDAY', 'Aniversário', 'EMAIL', 'Feliz Aniversário, {{employee_name}}! 🎂', '<h1>Feliz Aniversário! 🎂</h1><p>Olá <strong>{{employee_name}}</strong>,</p><p>Toda a equipe da <strong>{{company_name}}</strong> deseja a você um dia muito especial!</p><p>Que este novo ano de vida traga muitas realizações, saúde e felicidade.</p><p>Com carinho,<br>Equipe de RH</p>', 'HTML', '["employee_name", "company_name"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'BIRTHDAY', 'Aniversário', 'WHATSAPP', NULL, '🎂 *Feliz Aniversário, {{employee_name}}!*\n\nToda a equipe da *{{company_name}}* deseja um dia incrível!\n\n🎉 Que venha um ano cheio de conquistas!\n\nEquipe de RH ❤️', 'TEXT', '["employee_name", "company_name"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'CONTRACT_EXPIRING', 'Contrato Expirando', 'EMAIL', 'Aviso: Contrato expira em {{days_remaining}} dias - {{employee_name}}', '<h1>Aviso: Contrato Próximo ao Vencimento</h1><p>Prezado(a) <strong>{{manager_name}}</strong>,</p><p>O contrato do funcionário <strong>{{employee_name}}</strong> (Matrícula: {{employee_number}}) expirará em <strong>{{days_remaining}} dias</strong> ({{contract_end_date}}).</p><p><strong>Tipo de contrato:</strong> {{contract_type}}</p><p>Favor providenciar a renovação ou desligamento conforme necessário.</p><p>Atenciosamente,<br>Sistema de RH</p>', 'HTML', '["manager_name", "employee_name", "employee_number", "days_remaining", "contract_end_date", "contract_type"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'PROBATION_ENDING', 'Fim de Experiência', 'EMAIL', 'Aviso: Período de experiência termina em {{days_remaining}} dias - {{employee_name}}', '<h1>Aviso: Fim do Período de Experiência</h1><p>Prezado(a) <strong>{{manager_name}}</strong>,</p><p>O período de experiência do funcionário <strong>{{employee_name}}</strong> (Matrícula: {{employee_number}}) terminará em <strong>{{days_remaining}} dias</strong> ({{probation_end_date}}).</p><p>Favor realizar a avaliação de desempenho e definir a continuidade do contrato.</p><p>Atenciosamente,<br>Sistema de RH</p>', 'HTML', '["manager_name", "employee_name", "employee_number", "days_remaining", "probation_end_date"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'VACATION_EXPIRING', 'Férias Vencendo', 'EMAIL', 'Aviso: Férias vencem em {{days_remaining}} dias - {{employee_name}}', '<h1>Aviso: Período Aquisitivo de Férias Próximo ao Vencimento</h1><p>Prezado(a) <strong>{{manager_name}}</strong>,</p><p>O período aquisitivo de férias do funcionário <strong>{{employee_name}}</strong> (Matrícula: {{employee_number}}) vencerá em <strong>{{days_remaining}} dias</strong>.</p><p>Favor programar o gozo das férias conforme legislação (até 12 meses após o período aquisitivo).</p><p>Atenciosamente,<br>Sistema de RH</p>', 'HTML', '["manager_name", "employee_name", "employee_number", "days_remaining"]', 'pt_BR', TRUE, TRUE),
(UUID(), NULL, 'DSAR_REQUEST', 'Solicitação DSAR (LGPD)', 'EMAIL', 'Nova solicitação de acesso a dados (LGPD) - {{requester_name}}', '<h1>Solicitação DSAR - Lei Geral de Proteção de Dados</h1><p>Foi recebida uma nova solicitação de acesso a dados pessoais.</p><p><strong>Solicitante:</strong> {{requester_name}} ({{requester_type}})</p><p><strong>Tipo de solicitação:</strong> {{request_type}}</p><p><strong>Data da solicitação:</strong> {{request_date}}</p><p><strong>Prazo legal:</strong> 15 dias corridos</p><p>Favor processar conforme procedimento LGPD.</p><p>Atenciosamente,<br>DPO - Encarregado de Dados</p>', 'HTML', '["requester_name", "requester_type", "request_type", "request_date"]', 'pt_BR', TRUE, TRUE);
